oxy_webhelp_navlinks = {"mdb_evaluate_protection_options-d39536e36929":{"topics":[{"title":"Primary snapshot retention for MongoDB","shortdesc":"<p class=\"shortdesc\">Primary snapshot retention for MongoDB objects provides data protection and         recoverability by making it possible to set various retention policies. These policies         include hourly, daily, monthly, and yearly retention of snapshots to meet compliance,         business continuity, and disaster recovery requirements.<\/p>","href":"mongodb\/mdb_primary_snapshot_retention.html","attributes":{"data-id":"mdb_primary_snapshot_retention"},"menu":{"hasChildren":false},"tocID":"mdb_primary_snapshot_retention-d39536e36940","topics":[]},{"title":"Retention lock for MongoDB protection","shortdesc":"<p class=\"shortdesc\">A retention lock on an <span class=\"ph\">RSC<\/span> SLA Domain is a security feature that         prevents premature deletion of MongoDB snapshots.<\/p>","href":"mongodb\/mdb_protection_retention_lock.html","attributes":{"data-id":"mdb_protection_retention_lock"},"menu":{"hasChildren":false},"tocID":"mdb_protection_retention_lock-d39536e36951","topics":[]},{"title":"Multiple archival locations for MongoDB","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports multiple archival locations for MongoDB objects,         providing granular control over data archiving with up to two distinct archiving         policies.<\/p>","href":"mongodb\/mdb_multiple_archival_locations.html","attributes":{"data-id":"mdb_multiple_archival_locations"},"menu":{"hasChildren":false},"tocID":"mdb_multiple_archival_locations-d39536e36965","topics":[]},{"title":"Archiving for MongoDB snapshots","shortdesc":"<p class=\"shortdesc\">You can include an archival policy in an SLA Domain to archive MongoDB snapshots to an         archival location for long-term retention.<\/p>","href":"mongodb\/mdb_archiving_snapshots.html","attributes":{"data-id":"mdb_archiving_snapshots"},"menu":{"hasChildren":false},"tocID":"mdb_archiving_snapshots-d39536e36978","topics":[]},{"title":"Replication for MongoDB snapshots","shortdesc":"<p class=\"shortdesc\">You can use the SLA Domain replication policy to replicate MongoDB snapshots from one         Rubrik cluster to another for disaster recovery.<\/p>","href":"mongodb\/mdb_replication_snapshots.html","attributes":{"data-id":"mdb_replication_snapshots"},"menu":{"hasChildren":false},"tocID":"mdb_replication_snapshots-d39536e36989","topics":[]}]}};